(() => {
  const C = window.CITY, app = window.__CITY_APP, THREE = C.THREE;
  const centres = [[1692.6, -2659], [1714.1, -2668.7]];
  const near = (x, z) => centres.some(([cx, cz]) => Math.hypot(x - cx, z - cz) < 75);
  const meshes = [];
  const v = new THREE.Vector3();
  app.scene.traverse((o) => {
    if (!o.isMesh || o.isInstancedMesh || !o.visible || !o.geometry || !o.geometry.attributes.position) return;
    if (!o.geometry.boundingSphere) o.geometry.computeBoundingSphere();
    const s = o.geometry.boundingSphere; v.copy(s.center).applyMatrix4(o.matrixWorld);
    if (Math.hypot(v.x - 1700, v.z - 2663 * -1) < s.radius + 120) meshes.push(o);
  });
  const rc = new THREE.Raycaster();
  const f = (x) => +x.toFixed(2);
  const out = { pilot: !!(C.DON_VALLEY && C.DON_VALLEY.donValley), meshes: meshes.length, cars: [] };
  const list = [...app.trafficSystem.cars.map((c) => ['car', c]), ...app.trafficSystem.buses.map((c) => ['bus', c]), ...(app.highwayTraffic ? app.highwayTraffic.cars.map((c) => ['hwy', c]) : [])];
  for (const [kind, c] of list) {
    if (!Number.isFinite(c.x) || !near(c.x, c.z)) continue;
    rc.set(new THREE.Vector3(c.x, (c.y || 0) + 12, c.z), new THREE.Vector3(0, -1, 0));
    rc.far = 60;
    const hits = rc.intersectObjects(meshes, false).filter((h) => !/car|vehicle|Car/i.test(h.object.name));
    const top = hits[0];
    out.cars.push({ kind, x: f(c.x), z: f(c.z), y: f(c.y || 0), edgeH: c.edge ? [f(c.edge.h0 || 0), f(c.edge.h1 || 0)] : null, deck: f(C.deckHeightAt(c.x, c.z, (c.y || 0) + 0.5, 1)), hit: top ? [f(top.point.y), top.object.name] : null, hits: hits.slice(0, 4).map((h) => [f(h.point.y), h.object.name]) });
  }
  return out;
})()

